package com.example.mytableviewxmlimport android.view.LayoutInflaterimport android.view.Viewimport android.view.ViewGroupimport android.widget.TextViewimport androidx.recyclerview.widget.RecyclerViewdata class MyItem(val title: String, val description: String)class MyAdapter(private val dataList: List<MyItem>) :    RecyclerView.Adapter<MyAdapter.MyViewHolder>() {    // 各リストアイテムのビュー要素を保持する    class MyViewHolder(view: View) : RecyclerView.ViewHolder(view) {        val titleTextView: TextView = view.findViewById(R.id.item_title)        val descriptionTextView: TextView = view.findViewById(R.id.item_description)    }    // ここでlist_item_text.xmlをViewとして inflate (膨らませる)    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): MyViewHolder {        val view = LayoutInflater.from(parent.context)            .inflate(R.layout.list_item_text, parent, false)        return MyViewHolder(view)    }    // ここで、指定された位置（position）のデータを使ってViewHolderのUIを更新    override fun onBindViewHolder(holder: MyViewHolder, position: Int) {        val item = dataList[position]        holder.titleTextView.text = item.title        holder.descriptionTextView.text = item.description    }    // リスト内のアイテムの総数を返す    override fun getItemCount(): Int {        return dataList.size    }}